          <p class="font-semibold text-slate-900">Review a contact''s details</p>
          <p class="text-slate-600 text-sm">Click on a conversation and check the right panel for contact information</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Understanding the Inbox Layout',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Understanding the Inbox Layout';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Understanding the Inbox Layout

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'inbox-layout' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson inbox-layout not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What information appears in the left panel of the Conversations Inbox?', 
    '["The full message history","The list of conversations with contact names and message previews","Contact details and tags","Email templates"]'::jsonb,
    'The list of conversations with contact names and message previews',
    'The left panel shows your conversation list - who''s messaging you, preview text, timestamps, and status indicators.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you read the full message thread before replying?', 
    '["It''s required by the system","To understand the full context and avoid repeating information","It makes the reply send faster","To delete old messages"]'::jsonb,
    'To understand the full context and avoid repeating information',
    'Reading the full thread gives you context about previous conversations, preventing redundant questions and showing you understand the situation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can you learn from the contact details panel?', 
    '["Only the contact''s name","Tags, notes, appointments, opportunities, and past activity","Your account settings","Other users'' conversations"]'::jsonb,
    'Tags, notes, appointments, opportunities, and past activity',
    'The contact details panel provides a complete view of who you''re talking to - their history with you, where they are in your pipeline, and any notes or tags.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
